/* ==================== itinerary.js ==================== */
/* itinerary.js — shared by index.html (poster) and read.html (reader).
   Loads the itinerary markup partial for the current language, runs the
   today-auto-focus + tap-to-focus behaviour, then fires `itinerary:ready`
   (each render) so map.js and notes.js can (re)build. Reloads on language change. */
(function () {
  var MOUNT = document.getElementById('itinerary-mount');
  var I18N = window.I18N;

  // Temporary on-screen readout to diagnose notification deep-linking on iOS.
  function dbg(m) { try { var e = document.getElementById('dl-dbg'); if (e) e.textContent = 'dl: ' + m; } catch (_) {} }

  function runFocus() {
    var days = Array.prototype.slice.call(document.querySelectorAll('.day'));
    var bText = document.getElementById('banner-text');
    var jump = document.getElementById('jump');
    var today = new Date(); today.setHours(0, 0, 0, 0);
    var start = new Date('2026-07-31T00:00:00');
    var end = new Date('2026-08-13T00:00:00');
    var focusEl = null, focusNum = 0;

    days.forEach(function (d, i) {
      var dt = new Date(d.dataset.date + 'T00:00:00');
      if (dt.getTime() === today.getTime()) { focusEl = d; focusNum = i + 1; }

      // Days already behind us start collapsed to a compact summary so the list
      // stays short and today is easy to find. A clear hint invites first-time
      // users to tap them open; tapping toggles the day back and forth.
      if (dt.getTime() < today.getTime()) {
        d.classList.add('past', 'collapsed');
        var hint = document.createElement('div');
        hint.className = 'past-hint';
        hint.innerHTML =
          '<span class="ph-label"></span>' +
          '<svg class="ph-chev" width="16" height="16" viewBox="0 0 24 24" fill="none" ' +
          'stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">' +
          '<path d="M6 9l6 6 6-6"/></svg>';
        d.appendChild(hint);
      }

      d.addEventListener('click', function (e) {
        if (e.target.closest('a')) return;
        if (e.target.closest('.notes')) return;
        // A collapsed past day: first tap just expands it (no focus takeover).
        if (d.classList.contains('past')) {
          d.classList.toggle('collapsed');
          setPastHint(d);
          return;
        }
        days.forEach(function (x) { x.classList.remove('focus'); });
        d.classList.add('focus');
      });
    });

    // Keep each past day's hint label in sync with its collapsed/open state.
    function setPastHint(d) {
      var lbl = d.querySelector('.past-hint .ph-label');
      if (lbl) lbl.textContent = I18N.t(d.classList.contains('collapsed') ? 'past_expand' : 'past_collapse');
    }
    days.forEach(function (d) { if (d.classList.contains('past')) setPastHint(d); });

    function fmt(dt) {
      return dt.toLocaleDateString(I18N.locale(), { weekday: 'short', day: 'numeric', month: 'short' });
    }
    function setBanner(html) { if (bText) bText.innerHTML = html; }

    if (focusEl) {
      focusEl.classList.add('focus');
      var pills = focusEl.querySelector('.pills');
      if (pills && !pills.querySelector('.pill.today')) {
        var t = document.createElement('span');
        t.className = 'pill today'; t.textContent = I18N.lang === 'it' ? 'Oggi' : 'Today';
        pills.insertBefore(t, pills.firstChild);
      }
      setBanner(I18N.t('banner_today', { date: fmt(today), n: focusNum }));
      if (jump) {
        jump.textContent = I18N.t('jump_today');
        jump.style.display = 'inline';
        jump.onclick = function () { focusEl.scrollIntoView({ behavior: 'smooth', block: 'center' }); };
      }
      if (!/[#&]d=\d{4}-\d{2}-\d{2}/.test(location.hash)) {
        setTimeout(function () {
          focusEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }, 350);
      }
    } else if (today < start) {
      var n = Math.round((start - today) / 86400000);
      setBanner(I18N.t(n === 1 ? 'banner_starts_one' : 'banner_starts_many', { date: fmt(start), n: n }));
      if (days[0]) days[0].classList.add('focus');
    } else if (today > end) {
      setBanner(I18N.t('banner_complete'));
    } else {
      setBanner(I18N.t('banner_today_only', { date: fmt(today) }));
    }
  }

  // Deep-link from a push notification to a specific day. iOS often ignores the
  // notification's target URL, so we also read a target the service worker
  // stashes in a cache on tap, and listen for a message from the SW.
  function jumpToDay(date) {
    var el = document.querySelector('.day[data-date="' + date + '"]');
    if (!el) { dbg('no card for ' + date); return false; }
    Array.prototype.forEach.call(document.querySelectorAll('.day'), function (x) { x.classList.remove('focus'); });
    el.classList.add('focus');
    setTimeout(function () { el.scrollIntoView({ behavior: 'smooth', block: 'start' }); }, 200);
    dbg('jumped ' + date);
    return true;
  }
  function jumpToHash() {
    var m = (location.hash || '').match(/d=(\d{4}-\d{2}-\d{2})/);
    return m ? jumpToDay(m[1]) : false;
  }
  function clearNavTarget() {
    if ('caches' in window) caches.open('nav-target').then(function (c) { c.delete('t'); }).catch(function () {});
  }
  // Read the day the SW stashed on notification tap and jump to it. Retries a
  // few times because the app can become visible before the cache write lands,
  // and because iOS often resumes a suspended PWA without redelivering the SW
  // message — so this (not the postMessage) is the reliable path on iOS.
  function jumpFromCache(retries) {
    if (!('caches' in window)) return;
    if (typeof retries !== 'number') retries = 2;
    caches.open('nav-target').then(function (c) {
      return c.match('t').then(function (r) {
        if (!r) { if (retries > 0) setTimeout(function () { jumpFromCache(retries - 1); }, 300); return; }
        return r.text().then(function (day) {
          if (day && jumpToDay(day)) c.delete('t');
          else if (retries > 0) setTimeout(function () { jumpFromCache(retries - 1); }, 300);
        });
      });
    }).catch(function () {});
  }
  window.addEventListener('hashchange', jumpToHash);
  // When the app is brought back to the foreground (tapped notification, app
  // switcher), re-check the stashed target — covers the resumed-PWA case.
  document.addEventListener('visibilitychange', function () {
    if (document.visibilityState === 'visible') jumpFromCache(3);
  });
  window.addEventListener('pageshow', function () { jumpFromCache(2); });
  window.addEventListener('focus', function () { jumpFromCache(1); });
  // Ultimate fallback: iOS sometimes resumes a PWA without firing ANY of the
  // above and without redelivering the SW message. Poll the stashed target
  // while visible; jumpFromCache deletes it once consumed, so this is idempotent.
  setInterval(function () { if (document.visibilityState === 'visible') jumpFromCache(0); }, 1500);
  if (navigator.serviceWorker) {
    navigator.serviceWorker.addEventListener('message', function (e) {
      if (e.data && e.data.type === 'go-day' && e.data.day) { dbg('msg go-day ' + e.data.day); jumpToDay(e.data.day); clearNavTarget(); }
    });
  }

  function load(lang) {
    return fetch('itinerary.' + lang + '.html', { cache: 'no-cache' })
      .then(function (r) { return r.text(); })
      .then(function (html) {
        MOUNT.innerHTML = html;
        runFocus();
        jumpToHash();
        jumpFromCache();
        document.dispatchEvent(new CustomEvent('itinerary:ready'));
      })
      .catch(function () {
        if (MOUNT) MOUNT.innerHTML =
          '<div class="note"><b>' +
          (lang === 'it' ? 'Impossibile caricare l’itinerario.' : 'Couldn’t load the itinerary.') +
          '</b> ' +
          (lang === 'it'
            ? 'Apri questa pagina una volta con connessione per salvarla offline.'
            : 'Open this page once while online so it can save offline.') +
          '</div>';
      });
  }

  load(I18N.lang);
  I18N.onChange(function (lang) { load(lang); });
})();

/* ==================== map.js ==================== */
/* map.js — a little Australia map on each day card showing that day's leg.
   The whole map is a link to Google Maps (directions for a drive, a pin if
   stationary). Being an <a>, the card's tap-to-focus handler ignores it.
   Shared by index.html (poster) and read.html (reader). */
(function () {
  'use strict';

  // --- equirectangular projection tuned to the Australian mainland ---------
  var LNG_MIN = 112, LAT_N = -10, S = 10;
  var KX = Math.cos(25 * Math.PI / 180); // shrink longitude at ~25°S
  var W = (154 - LNG_MIN) * KX * S;       // ~380.6
  var H = (LAT_N - (-44)) * S;            // 340
  function px(lng) { return (lng - LNG_MIN) * KX * S; }
  function py(lat) { return (LAT_N - lat) * S; }

  // Coastline traced clockwise from Cape York (lat, lng). Decorative, not survey-grade.
  var OUTLINE = [
    [-10.7,142.5],[-15.5,145.3],[-16.9,145.8],[-19.3,146.8],[-21.1,149.2],
    [-23.4,150.9],[-25.3,153.1],[-27.5,153.2],[-28.6,153.6],[-30.3,153.1],
    [-33.9,151.3],[-37.1,149.9],[-37.8,148.5],[-39.1,146.4],[-38.4,144.9],
    [-38.9,143.5],[-38.0,140.7],[-35.6,138.1],[-34.7,135.9],[-32.8,134.2],
    [-31.5,131.2],[-31.7,128.9],[-33.9,121.9],[-35.0,117.9],[-34.4,115.1],
    [-32.0,115.7],[-28.8,114.6],[-24.9,113.7],[-21.8,114.1],[-20.3,118.6],
    [-17.95,122.2],[-16.4,123.0],[-14.8,128.1],[-12.4,130.8],[-12.0,133.0],
    [-12.2,136.8],[-14.7,135.5],[-17.6,140.8],[-12.6,141.9]
  ];
  var TASMANIA = [[-40.7,144.7],[-41.0,148.3],[-43.6,147.9],[-43.5,146.0]];

  function poly(pts) {
    return 'M' + pts.map(function (p) {
      return px(p[1]).toFixed(1) + ' ' + py(p[0]).toFixed(1);
    }).join(' L') + ' Z';
  }
  var AU_PATH = poly(OUTLINE);
  var TAS_PATH = poly(TASMANIA);

  // expose projection + outline so route.js can draw the whole loop
  window.AU_MAP = { px: px, py: py, W: W, H: H, AU_PATH: AU_PATH, TAS_PATH: TAS_PATH };

  // --- the day legs: [lat, lng, "Maps place name"] -------------------------
  var LEGS = {
    '2026-07-31': { from: [-33.75,151.29,'Dee Why NSW'],        to: [-32.24,148.60,'Dubbo NSW'] },
    '2026-08-01': { from: [-32.24,148.60,'Dubbo NSW'],          to: [-31.50,145.84,'Cobar NSW'] },
    '2026-08-02': { from: [-31.50,145.84,'Cobar NSW'],          to: [-31.96,141.47,'Broken Hill NSW'] },
    '2026-08-03': { from: [-31.96,141.47,'Broken Hill NSW'],    to: [-31.90,141.22,'Silverton NSW'], daytrip: true },
    '2026-08-04': { from: [-31.96,141.47,'Broken Hill NSW'],    to: [-31.24,136.79,'Pimba SA'] },
    '2026-08-05': { from: [-31.24,136.79,'Pimba SA'],           to: [-29.01,134.75,'Coober Pedy SA'] },
    '2026-08-06': { from: [-29.01,134.75,'Coober Pedy SA'],     to: [-24.42,131.83,'Kings Creek Station NT'] },
    '2026-08-07': { from: [-24.26,131.57,'Kings Canyon NT'],    to: [-23.68,132.92,'Redbank Gorge NT'] },
    '2026-08-08': { from: [-23.68,132.92,'Redbank Gorge NT'],   to: [-23.77,133.06,'Ellery Creek Big Hole NT'] },
    '2026-08-09': { from: [-23.77,133.06,'Ellery Creek Big Hole NT'], to: [-23.70,133.88,'Alice Springs NT'] },
    '2026-08-10': { from: [-23.70,133.88,'Alice Springs NT'],   to: [-27.30,133.62,'Marla SA'] },
    '2026-08-11': { from: [-27.30,133.62,'Marla SA'],           to: [-32.49,137.77,'Port Augusta SA'] },
    '2026-08-12': { from: [-32.49,137.77,'Port Augusta SA'],    to: [-34.51,144.84,'Hay NSW'] },
    '2026-08-13': { from: [-34.51,144.84,'Hay NSW'],            to: [-33.75,151.29,'Dee Why NSW'] }
  };

  function shortName(n) {
    return n.replace(/ (NSW|SA|NT|VIC|QLD|WA|TAS|Station)$/i, '');
  }
  function coord(p) { return p[0] + ',' + p[1]; }

  // A leg counts as "stationary" when start and end are within ~15 km.
  function isStationary(f, t) {
    var dLat = (f[0] - t[0]) * 111;
    var dLng = (f[1] - t[1]) * 111 * KX;
    return Math.sqrt(dLat * dLat + dLng * dLng) < 15;
  }

  function mapsUrl(f, t, stationary) {
    if (stationary) {
      return 'https://www.google.com/maps/search/?api=1&query=' + encodeURIComponent(t[2]);
    }
    return 'https://www.google.com/maps/dir/?api=1&origin=' +
      encodeURIComponent(coord(f)) + '&destination=' + encodeURIComponent(coord(t)) +
      '&travelmode=driving';
  }

  function buildMap(leg) {
    var f = leg.from, t = leg.to;
    var stationary = !leg.daytrip && isStationary(f, t);
    var fx = px(f[1]).toFixed(1), fy = py(f[0]).toFixed(1);
    var tx = px(t[1]).toFixed(1), ty = py(t[0]).toFixed(1);

    var marks;
    if (stationary) {
      marks = '<circle class="p-pulse" cx="' + tx + '" cy="' + ty + '" r="15"/>' +
              '<circle class="p-solo" cx="' + tx + '" cy="' + ty + '" r="8"/>';
    } else {
      marks = '<path class="route" d="M' + fx + ' ' + fy + ' L' + tx + ' ' + ty + '"/>' +
              '<circle class="p-from" cx="' + fx + '" cy="' + fy + '" r="6.5"/>' +
              '<circle class="p-to" cx="' + tx + '" cy="' + ty + '" r="8"/>';
    }

    var t18 = (window.I18N && window.I18N.t) ? window.I18N.t.bind(window.I18N) : function (k) { return k; };
    var cap = stationary
      ? '<span class="daymap-cap">' + escapeText(shortName(t[2])) +
        '<span class="hint">' + escapeText(t18('map_pin')) + '</span></span>'
      : '<span class="daymap-cap">' + escapeText(shortName(f[2])) +
        ' <span class="arr">→</span> ' + escapeText(shortName(t[2])) +
        '<span class="hint">' + escapeText(t18('map_directions')) + '</span></span>';

    var a = document.createElement('a');
    a.className = 'daymap';
    a.href = mapsUrl(f, t, stationary);
    a.target = '_blank';
    a.rel = 'noopener';
    a.setAttribute('aria-label', stationary
      ? 'Open ' + shortName(t[2]) + ' in Google Maps'
      : 'Directions from ' + shortName(f[2]) + ' to ' + shortName(t[2]) + ' in Google Maps');
    a.innerHTML =
      '<svg viewBox="0 0 ' + Math.ceil(W) + ' ' + Math.ceil(H) + '" ' +
        'xmlns="http://www.w3.org/2000/svg" role="img">' +
        '<path class="au" d="' + AU_PATH + '"/>' +
        '<path class="au" d="' + TAS_PATH + '"/>' +
        marks +
      '</svg>' + cap;
    return a;
  }

  function escapeText(s) {
    return String(s).replace(/[&<>]/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c];
    });
  }

  function render() {
    document.querySelectorAll('.day').forEach(function (dayEl) {
      if (dayEl.querySelector('.daymap')) return; // idempotent
      var leg = LEGS[dayEl.dataset.date];
      if (!leg) return;
      var el = buildMap(leg);
      // Insert right after the day-number row so it floats top-right and the
      // destination name + details wrap down its left side.
      var top = dayEl.querySelector('.toprow');
      if (top) top.insertAdjacentElement('afterend', el);
      else dayEl.insertBefore(el, dayEl.firstChild);
    });
  }

  // Runs on every (re)render of the itinerary — including language switches.
  document.addEventListener('itinerary:ready', render);
  if (document.querySelector('.day')) render();
})();

